import random, sys
seed = int(sys.argv[1]); count = int(sys.argv[2])
rng = random.Random(seed)
def digits(alpha, n):
    return ''.join(rng.choice(alpha) for _ in range(n))
def sep(s):
    # insert valid separators between digits occasionally
    if len(s) < 2 or rng.random() < 0.7: return s
    out = s[0]
    for c in s[1:]:
        if rng.random() < 0.2: out += '_'
        out += c
    return out
out = []
for _ in range(count):
    k = rng.random()
    if k < 0.15:
        n = rng.choice([1, 2, 8, 15, 16, 17, 20, 30])
        d = digits('0123456789abcdefABCDEF', n)
        if rng.random() < 0.3: d = 'f' * 16 if rng.random() < 0.5 else '1' + '0' * 16
        out.append(rng.choice(['0x', '0X']) + sep(d))
    elif k < 0.25:
        n = rng.choice([1, 5, 21, 22, 23, 30])
        d = digits('01234567', n)
        if rng.random() < 0.3: d = '1' + '7' * 21 if rng.random() < 0.5 else '2' + '0' * 21
        out.append(rng.choice(['0o', '0O']) + sep(d))
    elif k < 0.35:
        n = rng.choice([1, 10, 53, 54, 63, 64, 65, 70])
        out.append(rng.choice(['0b', '0B']) + sep(digits('01', n)))
    elif k < 0.5:
        # legacy octal / decimal-like
        n = rng.choice([1, 2, 5, 20, 21, 22, 23, 25])
        d = '0' + digits('01234567', n)
        if rng.random() < 0.3: d = '0' + rng.choice(['777777777777777777777', '1000000000000000000000', '7777777777777777777777', '0' * 30 + '17'])
        if rng.random() < 0.3: d = '0' + digits('0123456789', n)
        if rng.random() < 0.2: d += '.' + digits('0123456789', rng.randint(0, 5))
        if rng.random() < 0.1: d += 'e' + rng.choice(['', '-', '+']) + digits('0123456789', rng.randint(1, 3))
        out.append(d)
    else:
        ip = digits('0123456789', rng.choice([0, 1, 2, 5, 15, 16, 17, 18, 19, 20, 25, 40, 400]))
        if ip.startswith('0') and len(ip) > 1: ip = ip.lstrip('0') or '0'
        s = sep(ip)
        if rng.random() < 0.5 or not ip:
            s += '.' + sep(digits('0123456789', rng.choice([0, 1, 3, 10, 20, 30])))
            if not ip and s == '.': s = '.5'
        if s.endswith('.') and not ip: s += '5'
        if rng.random() < 0.4:
            s += rng.choice('eE') + rng.choice(['', '+', '-']) + sep(digits('0123456789', rng.choice([1, 2, 3, 4])))
        if s.startswith('.') or s[0].isdigit():
            out.append(s)
        else:
            out.append('1' + s)
print('\n'.join('lit ' + s for s in out))
