208	/// Minimal unsigned big integer (little-endian u32 limbs) used for exact expansions.
209	struct SmallBig {
210	    limbs: Vec<u32>,
211	}
212	
213	impl SmallBig {
214	    fn from_u64(v: u64) -> SmallBig {
215	        let mut limbs = vec![v as u32, (v >> 32) as u32];
216	        while limbs.last() == Some(&0) {
217	            limbs.pop();
218	        }
219	        SmallBig { limbs }
220	    }
