222	    fn mul_small(&mut self, m: u32) {
223	        let mut carry: u64 = 0;
224	        for l in self.limbs.iter_mut() {
225	            let t = (*l as u64) * (m as u64) + carry;
226	            *l = t as u32;
227	            carry = t >> 32;
228	        }
229	        if carry != 0 {
230	            self.limbs.push(carry as u32);
231	        }
232	    }
