234	    fn mul_pow5(&mut self, mut k: u32) {
235	        const POW5_13: u32 = 1_220_703_125; // 5^13, the largest power of 5 below 2^32
236	        while k >= 13 {
237	            self.mul_small(POW5_13);
238	            k -= 13;
239	        }
240	        if k > 0 {
241	            self.mul_small(5u32.pow(k));
242	        }
243	    }
