245	    fn shl(&mut self, bits: u32) {
246	        let words = (bits / 32) as usize;
247	        let rem = bits % 32;
248	        if rem != 0 {
249	            let mut carry = 0u32;
250	            for l in self.limbs.iter_mut() {
251	                let nl = (*l << rem) | carry;
252	                carry = *l >> (32 - rem);
253	                *l = nl;
254	            }
255	            if carry != 0 {
256	                self.limbs.push(carry);
257	            }
258	        }
259	        if words > 0 {
260	            let mut v = vec![0u32; words];
261	            v.extend_from_slice(&self.limbs);
262	            self.limbs = v;
263	        }
264	    }
