266	    /// Decimal digits (values 0..=9, most significant first) of a non-zero number.
267	    fn into_decimal(mut self) -> Vec<u8> {
268	        const BASE: u64 = 1_000_000_000;
269	        let mut chunks: Vec<u32> = Vec::with_capacity(self.limbs.len() * 32 / 29 + 1);
270	        while !self.limbs.is_empty() {
271	            let mut rem: u64 = 0;
272	            for l in self.limbs.iter_mut().rev() {
273	                let cur = (rem << 32) | (*l as u64);
