301	/// Exact decimal expansion of a finite positive double: value = 0.d1 d2 ... dk * 10^point,
302	/// with d1 != 0 and dk != 0 (digit values 0..=9).
303	struct ExactDecimal {
304	    digits: Vec<u8>,
305	    point: i32,
306	}
