308	fn exact_decimal(a: f64) -> ExactDecimal {
309	    let bits = a.to_bits();
310	    let biased = ((bits >> 52) & 0x7ff) as i32;
311	    let fraction = bits & ((1u64 << 52) - 1);
312	    let (mut m, mut e) = if biased == 0 {
313	        (fraction, -1074)
314	    } else {
315	        (fraction | (1u64 << 52), biased - 1075)
316	    };
317	    if m == 0 {
318	        return ExactDecimal { digits: vec![0], point: 1 };
319	    }
320	    let tz = m.trailing_zeros();
321	    m >>= tz;
322	    e += tz as i32;
323	    let mut big = SmallBig::from_u64(m);
324	    let (mut digits, point) = if e >= 0 {
325	        big.shl(e as u32);
326	        let d = big.into_decimal();
327	        let p = d.len() as i32;
328	        (d, p)
329	    } else {
330	        // m * 2^e = m * 5^-e / 10^-e
331	        big.mul_pow5((-e) as u32);
332	        let d = big.into_decimal();
333	        let p = d.len() as i32 + e;
334	        (d, p)
335	    };
336	    while digits.len() > 1 && digits.last() == Some(&0) {
337	        digits.pop();
338	    }
339	    ExactDecimal { digits, point }
340	}
