350	fn increment_digits(d: &mut [u8]) -> bool {
351	    for slot in d.iter_mut().rev() {
352	        if *slot == 9 {
353	            *slot = 0;
354	        } else {
355	            *slot += 1;
356	            return false;
357	        }
358	    }
