364	fn round_significant(dec: &ExactDecimal, p: usize, mode: Rounding) -> (Vec<u8>, i32) {
365	    let mut d: Vec<u8> = dec.digits.iter().take(p).copied().collect();
366	    d.resize(p, 0);
367	    let mut e = dec.point - 1;
368	    if dec.digits.len() > p {
369	        let next = dec.digits[p];
370	        let more = dec.digits.len() > p + 1; // digits are stripped of trailing zeros
371	        let up = match mode {
372	            Rounding::HalfUp => next >= 5,
373	            Rounding::HalfEven => next > 5 || (next == 5 && (more || d[p - 1] % 2 == 1)),
