1	//! Arbitrary-precision integers for JS BigInt (std only, no `unsafe`).
2	//!
3	//! Representation: sign + magnitude in little-endian `u64` limbs, always normalized (no high
4	//! zero limbs; zero has no limbs and is never negative), so the derived `Eq`/`Hash` are
5	//! value-based and `-0n` cannot exist.
6	//!
7	//! Algorithms: schoolbook multiplication below [`KARATSUBA_THRESHOLD`] limbs, Karatsuba above
8	//! (unbalanced operands are multiplied in balanced chunks); Knuth algorithm D for division
9	//! (2-by-1 reciprocal division for single-limb divisors); divide-and-conquer radix conversion
10	//! in both directions (power-of-two radices are converted bit-wise in linear time).
11	//!
12	//! Limits and error texts observed in the original `lumen` binary (reproduced here; the
13	//! message strings are exported as `MSG_*` constants for the engine to reuse):
14	//!
15	//! * `x << n` / `x >> -n` with n > 2^30 (`MAX_SHIFT_BITS`) and x != 0 throws
16	//!   `RangeError: BigInt is too large to allocate`; the limit is on the shift count only
17	//!   (`3n << 1073741824n` succeeds). `0n << hugeN` is 0; right shifts by huge counts give 0 or -1.
18	//! * `BigInt.asUintN(bits, x)` returns x unchanged when `x >= 0` and `bitlen(x) <= bits`;
19	//!   `BigInt.asIntN(bits, x)` returns x unchanged when `bitlen(|x|) < bits`. Otherwise lumen
20	//!   throws "BigInt is too large to allocate" if bits > 2^26 (`MAX_AS_N_BITS`), even when the
21	//!   result would be small (e.g. `BigInt.asUintN(2**26 + 1, -1n)`, `BigInt.asIntN(70000000,
22	//!   -(1n << 69999999n))`).
23	//! * `**` in lumen has no size check (huge results just hang); here a result that would need
24	//!   more than 2^30 bits (`MAX_POW_BITS`) fails with `BigIntError::TooLarge` (same message).
25	//!   `x ** -1n` -> "Exponent must be non-negative"; `0n ** 0n` is 1.
26	//! * Division/remainder by zero -> "Division by zero".
27	//! * `BigInt(1.5)`, `BigInt(NaN)`, `BigInt(Infinity)` -> RangeError
28	//!   "The number cannot be converted to a BigInt"; `BigInt("x")` -> SyntaxError
29	//!   "Cannot convert string to a BigInt" (also for `BigInt({})`, whose string is not numeric);
30	//!   `BigInt(undefined)`/`BigInt(null)`/`BigInt(Symbol())` -> TypeError
31	//!   "Cannot convert value to a BigInt".
32	//! * StringToBigInt (see [`BigInt::parse`]): trims whitespace (JS whitespace plus U+0085, like
33	//!   lumen's ToNumber), "" and "   " are 0n, a sign
34	//!   is allowed only for decimal ("-12" ok, "-0x10"/"+0x1" rejected), `0x`/`0o`/`0b` prefixes in
35	//!   either case, no separators, no decimal point/exponent, no `n` suffix, no "Infinity".
36	
37	#![allow(dead_code)]
38	
39	use std::cmp::Ordering;
40	use std::fmt;
41	
42	/// RangeError: `1n / 0n`, `1n % 0n`.
43	pub const MSG_DIVISION_BY_ZERO: &str = "Division by zero";
44	/// RangeError: `2n ** -1n`.
45	pub const MSG_NEGATIVE_EXPONENT: &str = "Exponent must be non-negative";
46	/// RangeError: `1n << 10000000000n`, `BigInt.asUintN(2**53 - 1, -1n)`.
47	pub const MSG_TOO_LARGE: &str = "BigInt is too large to allocate";
48	/// RangeError: `BigInt(1.5)`, `BigInt(NaN)`, `BigInt(Infinity)`.
49	pub const MSG_NUMBER_NOT_INTEGER: &str = "The number cannot be converted to a BigInt";
50	/// SyntaxError: `BigInt("x")`, `BigInt("1.5")`, `BigInt({})`.
51	pub const MSG_INVALID_STRING: &str = "Cannot convert string to a BigInt";
52	/// TypeError: `BigInt(undefined)`, `BigInt(null)`, `BigInt(Symbol())`, `BigInt.asIntN(64)`.
53	pub const MSG_CANNOT_CONVERT: &str = "Cannot convert value to a BigInt";
54	/// TypeError: ToBigInt on a Number, e.g. `BigInt.asIntN(1, 5)`, `new BigInt64Array([1])`.
55	pub const MSG_NUMBER_TO_BIGINT: &str = "Cannot convert a Number to a BigInt";
56	/// TypeError: `1n + 1`, `1n * 1.5`.
57	pub const MSG_MIX_TYPES: &str = "Cannot mix BigInt and other types, use explicit conversions";
58	/// TypeError: ToNumber on a BigInt, e.g. `+1n`, `Math.max(1n)`.
59	pub const MSG_TO_NUMBER: &str = "Cannot convert a BigInt value to a number";
60	/// TypeError: `new BigInt(1)`.
61	pub const MSG_NOT_CONSTRUCTOR: &str = "BigInt is not a constructor";
62	/// TypeError: `1n >>> 0n`.
63	pub const MSG_UNSIGNED_SHIFT: &str = "unsupported BigInt operator";
64	/// RangeError: `(255n).toString(37)` (note: Number's message is "toString() radix must be
65	/// between 2 and 36", with parentheses).
66	pub const MSG_RADIX: &str = "toString radix must be between 2 and 36";
67	/// TypeError: `BigInt.prototype.toString.call(1)`, `BigInt.prototype.valueOf.call(1)`.
68	pub const MSG_INCOMPATIBLE_RECEIVER: &str = "BigInt method called on incompatible receiver";
69	/// TypeError: `JSON.stringify(1n)`.
70	pub const MSG_JSON_SERIALIZE: &str = "Do not know how to serialize a BigInt";
71	/// RangeError from ToIndex: `BigInt.asIntN(-1, 1n)`, `BigInt.asIntN(2**53, 1n)`.
72	pub const MSG_INDEX_OUT_OF_RANGE: &str = "index out of range";
73	
74	/// Maximum shift count accepted by `<<` (and by `>>` with a negative count).
75	pub const MAX_SHIFT_BITS: u64 = 1 << 30;
76	/// Above this many bits `as_int_n`/`as_uint_n` refuse inputs that do not already fit.
77	pub const MAX_AS_N_BITS: u64 = 1 << 26;
78	/// Maximum result size of `pow` (lumen itself has no limit and simply hangs).
79	pub const MAX_POW_BITS: u64 = 1 << 30;
80	
81	/// Multiplication switches from schoolbook to Karatsuba at this many limbs (of the smaller
82	/// operand).
83	pub const KARATSUBA_THRESHOLD: usize = 40;
84	/// Radix conversion switches to divide-and-conquer above this many limbs.
85	const DC_TO_STRING_THRESHOLD: usize = 40;
86	/// Digit-string parsing switches to divide-and-conquer above this many digits.
87	const DC_PARSE_THRESHOLD: usize = 800;
88	
89	/// Errors of fallible BigInt operations; all are RangeErrors in JS.
90	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
91	pub enum BigIntError {
92	    DivisionByZero,
93	    NegativeExponent,
94	    TooLarge,
95	}
96	
97	impl BigIntError {
98	    /// The exact message lumen uses.
99	    pub fn message(self) -> &'static str {
100	        match self {
101	            BigIntError::DivisionByZero => MSG_DIVISION_BY_ZERO,
102	            BigIntError::NegativeExponent => MSG_NEGATIVE_EXPONENT,
103	            BigIntError::TooLarge => MSG_TOO_LARGE,
104	        }
105	    }
106	
107	    /// The JS error constructor to throw (always "RangeError").
108	    pub fn js_error_name(self) -> &'static str {
109	        "RangeError"
110	    }
111	}
112	
113	impl fmt::Display for BigIntError {
114	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
115	        f.write_str(self.message())
116	    }
117	}
118	
119	impl std::error::Error for BigIntError {}
120	
121	/// Error type of [`BigInt::pow`].
122	pub type PowError = BigIntError;
123	
124	#[derive(Clone, PartialEq, Eq, Hash, Debug, Default)]
125	pub struct BigInt {
126	    /// True only for values < 0.
127	    neg: bool,
128	    /// Magnitude, little-endian, no high zero limbs.
129	    mag: Vec<u64>,
130	}

