560	fn chunk_base(radix: u32) -> (u64, usize) {
561	    let r = radix as u64;
562	    let mut base = r;
563	    let mut k = 1;
564	    while let Some(nb) = base.checked_mul(r) {
565	        base = nb;
566	        k += 1;
567	    }
568	    (base, k)
569	}
570	
571	fn digit_char(d: u64) -> u8 {
572	    b"0123456789abcdefghijklmnopqrstuvwxyz"[d as usize]
573	}
574	
575	/// Bit-wise conversion for radix 2^bpd.
576	fn to_string_pow2(mag: &[u64], bpd: u32, out: &mut Vec<u8>) {
577	    let total = bit_len_mag(mag);
578	    let bpd64 = bpd as u64;
579	    let ndigits = total.div_ceil(bpd64);
580	    let mask = (1u64 << bpd) - 1;
581	    for k in (0..ndigits).rev() {
582	        let pos = k * bpd64;
583	        let limb = (pos / 64) as usize;
584	        let off = (pos % 64) as u32;
585	        let mut v = mag[limb] >> off;
586	        if off + bpd > 64 && limb + 1 < mag.len() {
587	            v |= mag[limb + 1] << (64 - off);
588	        }
589	        out.push(digit_char(v & mask));
590	    }
591	}
592	
593	/// Naive conversion: repeated division by the chunk base. Appends the digits of `x`,
594	/// left-padded with zeros to `pad_to` digits (0 = no padding).
595	fn to_string_naive(x: &[u64], radix: u32, pad_to: usize, out: &mut Vec<u8>) {
596	    let (base, k) = chunk_base(radix);
597	    let rec = Reciprocal::new(base);
598	    let r = radix as u64;
599	    let mut cur = x.to_vec();
600	    trim(&mut cur);
601	    let mut chunks: Vec<u64> = Vec::with_capacity(cur.len() + 1);
602	    while !cur.is_empty() {
603	        chunks.push(div_small_in_place(&mut cur, &rec));
604	    }
605	    let mut digits: Vec<u8> = Vec::with_capacity(chunks.len() * k);
606	    for (idx, &c) in chunks.iter().rev().enumerate() {
607	        let mut tmp = [b'0'; 64];
608	        let mut v = c;
609	        for slot in tmp[..k].iter_mut().rev() {
610	            *slot = digit_char(v % r);
611	            v /= r;
612	        }
613	        if idx == 0 {
614	            let skip = tmp[..k].iter().position(|&ch| ch != b'0').unwrap_or(k);
615	            digits.extend_from_slice(&tmp[skip..k]);
616	        } else {
617	            digits.extend_from_slice(&tmp[..k]);
618	        }
619	    }
620	    if digits.len() < pad_to {
621	        out.resize(out.len() + (pad_to - digits.len()), b'0');
622	    }
623	    out.extend_from_slice(&digits);
624	}
625	
626	/// Divide-and-conquer conversion. `powers[i]` = base^(2^i); requires x < powers[k]^2.
627	/// When `pad` is set the output is left-padded to chunk_digits * 2^(k+1) digits.
628	fn to_string_dc(
629	    x: &[u64],
630	    k: usize,
631	    pad: bool,
632	    radix: u32,
633	    chunk_digits: usize,
634	    powers: &[Vec<u64>],
635	    out: &mut Vec<u8>,
636	) {
637	    let width = chunk_digits << (k + 1);
638	    if x.len() <= DC_TO_STRING_THRESHOLD || k == 0 {
639	        to_string_naive(x, radix, if pad { width } else { 0 }, out);
640	        return;
641	    }
642	    let (q, r) = if x.is_empty() {
643	        (Vec::new(), Vec::new())
644	    } else {
645	        divrem_mag(x, &powers[k])
646	    };
647	    if !pad && q.is_empty() {
648	        to_string_dc(&r, k - 1, false, radix, chunk_digits, powers, out);
649	    } else {
650	        to_string_dc(&q, k - 1, pad, radix, chunk_digits, powers, out);
651	        to_string_dc(&r, k - 1, true, radix, chunk_digits, powers, out);
652	    }
653	}
654	
655	fn mag_to_string(mag: &[u64], radix: u32, out: &mut Vec<u8>) {
656	    if mag.is_empty() {
657	        out.push(b'0');
658	        return;
659	    }
660	    if radix.is_power_of_two() {
661	        to_string_pow2(mag, radix.trailing_zeros(), out);
662	        return;
663	    }
664	    if mag.len() <= DC_TO_STRING_THRESHOLD {
665	        to_string_naive(mag, radix, 0, out);
666	        return;
667	    }
668	    let (base, chunk_digits) = chunk_base(radix);
669	    // powers[i] = base^(2^i); stop once powers[k]^2 is certainly > mag.
670	    let mut powers: Vec<Vec<u64>> = vec![vec![base]];
671	    loop {
672	        let last = powers.last().map_or(0, |p| p.len());
673	        if 2 * last >= mag.len() + 2 {
674	            break;
675	        }
676	        let sq = {
677	            let p = &powers[powers.len() - 1];
678	            mul_mag(p, p)
679	        };
680	        powers.push(sq);
681	    }
682	    let k = powers.len() - 1;
683	    to_string_dc(mag, k, false, radix, chunk_digits, &powers, out);
684	}
685	
686	fn digit_value(c: u8) -> u32 {
687	    match c {
688	        b'0'..=b'9' => (c - b'0') as u32,
689	        b'a'..=b'z' => (c - b'a') as u32 + 10,
690	        b'A'..=b'Z' => (c - b'A') as u32 + 10,
691	        _ => 99,
692	    }
693	}
694	
695	/// Magnitude from digit values (each < radix), most significant first.
696	fn mag_from_digit_values(d: &[u8], radix: u32) -> Vec<u64> {
697	    let start = d.iter().position(|&x| x != 0).unwrap_or(d.len());
698	    let d = &d[start..];
699	    if d.is_empty() {
700	        return Vec::new();
701	    }
702	    if radix.is_power_of_two() {
703	        let bpd = radix.trailing_zeros() as usize;
704	        let mut out = vec![0u64; (d.len() * bpd).div_ceil(64)];
705	        for (k, &v) in d.iter().rev().enumerate() {
706	            let pos = k * bpd;
707	            let limb = pos / 64;
708	            let off = pos % 64;
709	            out[limb] |= (v as u64) << off;
710	            if off + bpd > 64 {
711	                out[limb + 1] |= (v as u64) >> (64 - off);
712	            }
713	        }
714	        trim(&mut out);
715	        return out;
716	    }
717	    let (base, chunk_digits) = chunk_base(radix);
718	    if d.len() <= DC_PARSE_THRESHOLD {
719	        return parse_naive(d, radix, chunk_digits);
720	    }
721	    let mut powers: Vec<Vec<u64>> = vec![vec![base]];
722	    parse_dc(d, radix, chunk_digits, &mut powers)
723	}
724	
725	fn parse_naive(d: &[u8], radix: u32, chunk_digits: usize) -> Vec<u64> {
726	    let mut acc: Vec<u64> = Vec::with_capacity(d.len() / chunk_digits + 1);
727	    let first = match d.len() % chunk_digits {
728	        0 => chunk_digits.min(d.len()),
729	        r => r,
730	    };
731	    let mut i = 0;
732	    let mut len = first;
733	    while i < d.len() {
734	        let chunk = &d[i..i + len];
735	        let mut v: u64 = 0;
736	        for &x in chunk {
737	            v = v * radix as u64 + x as u64;
738	        }
739	        let mul = (radix as u64).pow(len as u32);
740	        mul_small_add_in_place(&mut acc, mul, v);
741	        i += len;
742	        len = chunk_digits;
743	    }
744	    trim(&mut acc);
745	    acc
746	}
747	
748	fn parse_dc(d: &[u8], radix: u32, chunk_digits: usize, powers: &mut Vec<Vec<u64>>) -> Vec<u64> {
749	    if d.len() <= DC_PARSE_THRESHOLD {
750	        return parse_naive(d, radix, chunk_digits);
751	    }
752	    // Low part: chunk_digits * 2^j digits, the largest such count below d.len().
753	    let mut j = 0;
754	    while (chunk_digits << (j + 1)) < d.len() {
755	        j += 1;
756	    }
