560	fn chunk_base(radix: u32) -> (u64, usize) {
561	    let r = radix as u64;
562	    let mut base = r;
563	    let mut k = 1;
564	    while let Some(nb) = base.checked_mul(r) {
565	        base = nb;
566	        k += 1;
567	    }
568	    (base, k)
569	}
